class _V300WorldHubPageState extends State<V300WorldHubPage> {
  Map<String,dynamic>? party; bool busy=false;
  @override void initState(){super.initState(); if(widget.controller.serverConnected) unawaited(_loadParty());}
  Future<void> _loadParty() async { try{final r=await widget.controller.api.myPartyV300(); if(mounted)setState(()=>party=r['party'] is Map?Map<String,dynamic>.from(r['party'] as Map):null);}catch(_){}}
  Future<void> _createParty() async { setState(()=>busy=true); try{final r=await widget.controller.api.createPartyV300(gameKey:widget.controller.homeGames.first.id); if(mounted)setState(()=>party=r['party'] is Map?Map<String,dynamic>.from(r['party'] as Map):null); HapticFeedback.mediumImpact();}catch(e){if(mounted)showToast(context,friendlyErrorMessage(e,widget.controller.localeCode));} if(mounted)setState(()=>busy=false); }
  @override Widget build(BuildContext context){
    final c=widget.controller;
    return Scaffold(appBar:AppBar(title:Text(L.t(c.localeCode,'worldHub'))),body:ListView(padding:const EdgeInsets.all(16),children:[
      SizedBox(height:116,child:Center(child:Lottie.asset('assets/lottie/world/world_pulse.json',repeat:true))),
      Text(L.t(c.localeCode,'worldExperience'),textAlign:TextAlign.center,style:TextStyle(fontSize:24,fontWeight:FontWeight.w900,color:Theme.of(context).colorScheme.primary)),
      const SizedBox(height:16),
      LayoutBuilder(builder:(context,box){final wide=box.maxWidth>760; final cards=<Widget>[
        _V300HubCard(icon:Icons.flash_on_rounded,title:L.t(c.localeCode,'quickMatch'),subtitle:L.t(c.localeCode,'matchmaking'),onTap:()=>showGameLobby(context,c,c.homeGames.first)),
        _V300HubCard(icon:Icons.groups_2_rounded,title:party==null?L.t(c.localeCode,'createParty'):L.t(c.localeCode,'myParty'),subtitle:party?['code']?.toString()??L.t(c.localeCode,'partyHint'),onTap:busy?null:_createParty),
        _V300HubCard(icon:Icons.visibility_rounded,title:L.t(c.localeCode,'spectate'),subtitle:L.t(c.localeCode,'spectateHint'),onTap:()=>Navigator.push(context,MaterialPageRoute(builder:(_)=>R11SocialWorldPage(controller:c)))),
        _V300HubCard(icon:Icons.wifi_protected_setup_rounded,title:L.t(c.localeCode,'reconnect'),subtitle:L.t(c.localeCode,'reconnectHint'),onTap:c.activeRoomCode==null?null:() async {try{await c.api.reconnectRoomV300(c.activeRoomCode!);if(context.mounted)showToast(context,L.t(c.localeCode,'reconnect'));}catch(e){if(context.mounted)showToast(context,friendlyErrorMessage(e,c.localeCode));}}),
      ]; return GridView.count(crossAxisCount:wide?4:2,shrinkWrap:true,physics:const NeverScrollableScrollPhysics(),mainAxisSpacing:10,crossAxisSpacing:10,childAspectRatio:wide?1.25:.95,children:cards);}),
      const SizedBox(height:16),
      R9Section(child:Wrap(spacing:12,runSpacing:10,children:[Chip(avatar:const Icon(Icons.security_rounded,size:16),label:Text(L.t(c.localeCode,'afkProtection'))),Chip(avatar:const Icon(Icons.smart_toy_outlined,size:16),label:Text(L.t(c.localeCode,'serverControl'))),Chip(avatar:const Icon(Icons.emoji_events_outlined,size:16),label:Text(L.t(c.localeCode,'seasonal'))),Chip(avatar:const Icon(Icons.speed_rounded,size:16),label:Text(L.t(c.localeCode,'matchmaking')))])),
    ]));
  }
}

class _V300HubCard extends StatelessWidget{
  const _V300HubCard({required this.icon,required this.title,required this.subtitle,this.onTap});
  final IconData icon; final String title,subtitle; final VoidCallback? onTap;
  @override Widget build(BuildContext context)=>InkWell(onTap:onTap,borderRadius:BorderRadius.circular(24),child:Ink(padding:const EdgeInsets.all(16),decoration:BoxDecoration(borderRadius:BorderRadius.circular(24),gradient:LinearGradient(colors:[Theme.of(context).colorScheme.primary.withValues(alpha:.14),Theme.of(context).colorScheme.surface]),border:Border.all(color:Theme.of(context).colorScheme.primary.withValues(alpha:.18))),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Icon(icon,color:Theme.of(context).colorScheme.primary,size:30),const Spacer(),Text(title,style:const TextStyle(fontWeight:FontWeight.w900,fontSize:15)),const SizedBox(height:5),Text(subtitle,maxLines:3,overflow:TextOverflow.ellipsis,style:TextStyle(fontSize:10,height:1.35,color:Theme.of(context).colorScheme.onSurface.withValues(alpha:.65)))])));
}

