class _V300AdminWorldOpsPanelState extends State<V300AdminWorldOpsPanel>{Map<String,dynamic>? data;bool loading=false;@override void initState(){super.initState();if(widget.controller.serverConnected)unawaited(load());}Future<void> load()async{setState(()=>loading=true);try{data=await widget.controller.api.adminEconomyAuditV300(refresh:true);}catch(e){if(mounted)showToast(context,e.toString());}if(mounted)setState(()=>loading=false);}@override Widget build(BuildContext context){final s=data?['summary'] is Map?Map<String,dynamic>.from(data!['summary'] as Map):<String,dynamic>{};final events=data?['events'] is List?data!['events'] as List:const[];return RefreshIndicator(onRefresh:load,child:ListView(padding:const EdgeInsets.all(12),children:[Wrap(spacing:8,runSpacing:8,children:[_AdminMetric(icon:'🛡️',label:'Open audit',value:'${s['open']??0}'),_AdminMetric(icon:'🚨',label:'Critical',value:'${s['critical']??0}'),_AdminMetric(icon:'⚠️',label:'High risk',value:'${s['high']??0}'),_AdminMetric(icon:'📊',label:'24h',value:'${s['last_24h']??0}')]),const SizedBox(height:12),const _AdminInfo(text:'WORLD OPS يجمع تدقيق الاقتصاد مع مؤشرات الجلسات، الحماية من إساءة الاستخدام، ومراجعة المعاملات عالية المخاطر. كل الحكم المالي يبقى خادميًا.'),const SizedBox(height:8),if(loading)const LinearProgressIndicator(),...events.take(80).map((e){final m=e is Map?Map<String,dynamic>.from(e):<String,dynamic>{};return Card(child:ListTile(leading:CircleAvatar(child:Text('${m['risk_score']??0}')),title:Text(m['type']?.toString()??'audit'),subtitle:Text('status: ${m['status']??'open'} • user ${m['user_id']??'-'}'),trailing:const Icon(Icons.chevron_right)));})]));}}
